-- =====================================================================
-- SEQUENS TRACKER FEED  (run in the SAME Supabase project, AFTER tracker-backend.sql)
-- The objective map flows into the objectives table.
-- NO pupil data. Safe to run before ICO registration.
-- Seeds all 96 Y6D Autumn 1 objectives with their quick_check hinge
-- (the named misconception). Maths and Science hinges are from White Rose.
-- Writing, Reading and IPC hinges are SEQUENS-suggested and are flagged as such
-- in the hinge_suggested column, so the database records what is scheme vs suggested.
-- The daily layer (assessments, source=objective, kind=daily) binds to NAMED
-- pupils and therefore waits for ICO. This file does not touch pupils.
-- =====================================================================

-- 1. one hinge per lesson: the misconception the quick_check catches
alter table objectives add column if not exists hinge text;
alter table objectives add column if not exists hinge_suggested boolean default false;

-- 2. make (school_id, code) unique so this seed is idempotent (safe to re-run)
create unique index if not exists objectives_school_code_uq on objectives (school_id, code);

-- 3. seed the objectives (lead-only write is enforced by RLS: run as the Y6 lead)
insert into objectives (school_id, subject, code, statement, hinge, hinge_suggested)
values
  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Maths', 'WRM-Y6-A1-PV-1', 'Numbers to 1,000,000: Read, write, order and compare numbers up to 10,000,000 and determine the value of each digit. Solve number and practical problems that involve the above.', 'Thinks the place value columns run ones, tens, hundreds, thousands, millions, skipping ten-thousands and hundred-thousands.', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Maths', 'WRM-Y6-A1-PV-2', 'Numbers to 10,000,000: Read, write, order and compare numbers up to 10,000,000 and determine the value of each digit. Solve number and practical problems that involve the above.', 'Cannot read a 7-digit number written without commas, or misplaces the commas.', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Maths', 'WRM-Y6-A1-PV-3', 'Read and write numbers to 10,000,000: Read, write, order and compare numbers up to 10,000,000 and determine the value of each digit. Solve number and practical problems that involve the above.', 'Drops or misreads placeholders when writing large numbers in words (for example 5,208,001).', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Maths', 'WRM-Y6-A1-PV-4', 'Powers of 10: Read, write, order and compare numbers up to 10,000,000 and determine the value of each digit. Solve number and practical problems that involve the above.', 'Thinks multiplying by 10 then by 10 again is the same as multiplying by 20.', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Maths', 'WRM-Y6-A1-PV-5', 'Number line to 10,000,000: Read, write, order and compare numbers up to 10,000,000 and determine the value of each digit. Solve number and practical problems that involve the above.', 'Gives the midpoint wrongly, for example calling the midpoint of 1,000,000 and 2,000,000 as 1,000,005.', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Maths', 'WRM-Y6-A1-PV-6', 'Compare and order any integers: Read, write, order and compare numbers up to 10,000,000 and determine the value of each digit. Solve number and practical problems that involve the above.', 'Compares on the leading digit alone, so thinks 56,700 is greater than 201,000 because 5 is greater than 2.', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Maths', 'WRM-Y6-A1-PV-7', 'Round any integer: Round any whole number to a required degree of accuracy. Solve number and practical problems that involve the above.', 'Looks at the digit being rounded rather than the next digit when rounding.', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Maths', 'WRM-Y6-A1-PV-8', 'Negative numbers: Use negative numbers in context, and calculate intervals across zero. Solve number and practical problems that involve the above.', 'Thinks negative 5 is greater than negative 3 because 5 is greater than 3.', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Science', 'WRS-Y6-A1-LTH-1', 'Conditions for life: Describe how living things are classified into broad groups according to common observable characteristics and based on similarities and differences, including microorganisms, plants and animals.', 'Thinks plants are non-living because they do not appear to move.', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Science', 'WRS-Y6-A1-LTH-2', 'Group organisms: Describe how living things are classified into broad groups according to common observable characteristics and based on similarities and differences, including microorganisms, plants and animals.', 'Thinks all animals that live in the sea are fish.', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Science', 'WRS-Y6-A1-LTH-3', 'Classify animals: Give reasons for classifying plants and animals based on specific characteristics.', 'Classifies animals by habitat or movement rather than features, so calls a whale a fish.', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Science', 'WRS-Y6-A1-LTH-4', 'Classify plants: Give reasons for classifying plants and animals based on specific characteristics.', 'Classifies a mushroom as a plant because it has a stem.', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Science', 'WRS-Y6-A1-LTH-5', 'Microorganisms: Describe how living things are classified into broad groups according to common observable characteristics and based on similarities and differences, including microorganisms, plants and animals.', 'Thinks all bacteria are harmful.', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Science', 'WRS-Y6-A1-LTH-6', 'Classify organisms: Describe how living things are classified into broad groups according to common observable characteristics and based on similarities and differences, including microorganisms, plants and animals.', 'Thinks microorganisms cannot be classified.', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'Science', 'WRS-Y6-A1-LTH-7', 'Carl Linnaeus: Describe how living things are classified into broad groups according to common observable characteristics and based on similarities and differences, including microorganisms, plants and animals.', 'Thinks Linnaeus created the classification system we use today.', false),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W1-1', 'To analyze how an author uses language choices to create a tense atmospheric narrative opening.', 'Slips between tenses within the piece.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W1-2', 'To use precise expanded noun phrases to describe the physical details of a setting.', 'Piles on adjectives without the phrase adding real information.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W1-3', 'To use fronted adverbials to establish context, time, and place in a setting description.', 'Forgets the comma after the fronted adverbial.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W1-4', 'To select and apply figurative language devices (similes and metaphors) to enhance narrative imagery.', 'Writes a simile that decorates but does not deepen the image.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W1-5', 'To construct a cohesive narrative opening paragraph that establishes an immersive setting.', 'Repeats the same connective instead of varying the cohesion.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W2-1', 'To analyze how a character is introduced through a unique, controlled narrative perspective.', 'Loses the character''s voice partway through.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W2-2', 'To develop and maintain a consistent, authentic first-person narrative voice.', 'Loses the character''s voice partway through.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W2-3', 'To show character traits and feelings through internal thoughts and physical actions rather than telling.', 'Writes to the task without checking it against the success criteria.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W2-4', 'To use relative clauses (who, which, whose, that) to add depth and precision when describing secondary characters.', 'Drops or misplaces the commas, or uses the wrong relative pronoun.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W3-1', 'To identify key plot milestones in a novel and explore how an author builds internal conflict.', 'Writes to the task without checking it against the success criteria.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W3-2', 'To draft a structured character-focused paragraph introducing a key protagonist.', 'Starts a new paragraph in the wrong place.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W3-3', 'To punctuate direct speech accurately to create realistic dialogue between characters.', 'Puts the comma or full stop outside the speech marks.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W3-4', 'To integrate dialogue within a scene to reveal character betrayals and shift relationships.', 'Puts the comma or full stop outside the speech marks.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W3-5', 'To use active and passive voice deliberately to alter emphasis during a high-stakes conflict scene.', 'Shifts between active and passive without a purpose.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W4-1', 'To vary sentence lengths and clause structures to control pacing and escalate dramatic tension.', 'Uses only long sentences, so tension is flat.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W4-2', 'To analyze structural narrative endings and draft a resolution where characters learn a lesson about empathy.', 'Starts a new paragraph in the wrong place.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W4-3', 'To use advanced punctuation (colons, semi-colons, dashes, and brackets) to add parenthesis or mark boundaries between independent clauses.', 'Uses advanced punctuation in the wrong place.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W4-4', 'To apply conjunctive adverbials and structural cohesive devices to link ideas smoothly across narrative paragraphs.', 'Repeats the same connective instead of varying the cohesion.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W4-5', 'To evaluate, refine, edit, and proofread a narrative scene draft for sentence fluency and grammatical accuracy.', 'Only fixes spelling and misses meaning and flow.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W5-1', 'To identify the audience, purpose, and layout features of a formal recount text or diary shift.', 'Mixes formal and informal language.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W5-2', 'To compare formal and informal registers, transforming casual spoken dialogue into a formal written record.', 'Puts the comma or full stop outside the speech marks.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W5-3', 'To maintain absolute past tense consistency (simple, progressive, and perfect forms) across a multi-paragraph recount.', 'Slips between tenses within the piece.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W5-4', 'To plan and draft a structured formal recount from an alternative character''s viewpoint.', 'Plans as a list of events with no shape.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W6-1', 'To analyze the structural features and rhetorical techniques used in formal explanation texts.', 'Plans as a list of events with no shape.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W6-2', 'To use the passive voice to create an objective, matter-of-fact tone when explaining an incident or policy.', 'Shifts between active and passive without a purpose.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W6-3', 'To use bullet points and colons correctly to introduce a formal list of rules or precepts.', 'Uses advanced punctuation in the wrong place.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W6-4', 'To plan an explanation text breaking down the deeper moral meaning behind a formal precept.', 'Plans as a list of events with no shape.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W6-5', 'To draft a formal explanation text using cohesive devices to link ideas smoothly across distinct paragraph blocks.', 'Repeats the same connective instead of varying the cohesion.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W7-1', 'To identify the key features and persuasive techniques used to champion a social cause.', 'States an opinion without evidence to back it.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W7-2', 'To use modal verbs and adverbs of possibility to strengthen the authority of a written argument advocating for inclusion and kindness.', 'Uses a modal verb but not to strengthen the argument.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W7-3', 'To write persuasive paragraphs using formal language to address the importance of standing up for others.', 'Mixes formal and informal language.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W7-4', 'To use cohesive devices to link evidence and sustain a clear, logical viewpoint against isolation and bullying.', 'Repeats the same connective instead of varying the cohesion.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Writing', 'ENG-Y6-A1-W7-5', 'To edit writing for clarity, proofread for structural cohesion, and publish a final persuasive text / End of Unit Assessment.', 'Repeats the same connective instead of varying the cohesion.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'IPC', 'IPC-Y6-A1-W1-1', 'Lesson A: Entry Point & Timeline: Construct a regional timeline focusing on global civilisations around 900 CE.', 'Thinks older civilisations were simpler or less advanced.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'IPC', 'IPC-Y6-A1-W1-2', 'Lesson B: Knowledge Harvest: Gauge baseline student vocabulary regarding ancient history, archaeology, and chronology.', 'Thinks older civilisations were simpler or less advanced.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'IPC', 'IPC-Y6-A1-W2-1', 'Lesson A: History (3.01): Formulate inquiry questions related to different geographic perspectives of Mesoamerica around 900 CE.', 'Treats one map or source as the whole truth.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'IPC', 'IPC-Y6-A1-W2-2', 'Lesson B: History (3.05): Identify the geographical features, infrastructure, and city-state layouts of the Maya civilization.', 'Assumes ancient cities had no planning or scale.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'IPC', 'IPC-Y6-A1-W3-1', 'Lesson A: History (3.04): Understand how historians build inferences about daily Mayan life based on archaeological artifacts.', 'Treats an artefact as proof rather than evidence to interpret.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'IPC', 'IPC-Y6-A1-W3-2', 'Lesson B: History (3.05): Analyse social hierarchies, trade routes, and the roles of rulers vs. artisans within Maya society.', 'Assumes everyone in the past lived the same way.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'IPC', 'IPC-Y6-A1-W4-1', 'Lesson A: History (3.10): Evaluate how ancient Mayan ideas, agricultural methods, and beliefs have influenced modern societies.', 'Thinks nothing from 900 CE still matters today.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'IPC', 'IPC-Y6-A1-W4-2', 'Lesson B: Cultural Myths: Explore Mayan polytheism, ritual practices, and sacred mythology (e.g., the Popul Vuh).', 'Confuses myth and belief with historical fact.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'IPC', 'IPC-Y6-A1-W5-1', 'Lesson A: History (3.11): Examine Mayan technological developments, tracking their sophisticated logographic writing system and codices.', 'Assumes ancient people had no science or learning.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'IPC', 'IPC-Y6-A1-W5-2', 'Lesson B: Mathematical Advancements: Study the structural development of the Mayan base-20 numbering system and solar calendars.', 'Thinks base-20 is just a wrong version of base-10.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'IPC', 'IPC-Y6-A1-W6-1', 'Lesson A: History (3.02 & 3.12): Analyse theories behind the Classic Maya collapse, evaluating how multiple causes contribute to changes in society.', 'Looks for one single cause instead of several interacting ones.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'IPC', 'IPC-Y6-A1-W6-2', 'Exit point prep.', 'Judges one civilisation as better rather than comparing fairly.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'IPC', 'IPC-Y6-A1-W7-1', 'Lesson B: Exit Point: Execute a comparative civilisation synthesis block, presenting ancient regional outcomes.', 'Judges one civilisation as better rather than comparing fairly.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Reading', 'READ-Y6-A1-W1-1', 'Vocabulary (2a: word meaning in context): To work out the meaning of unfamiliar words in "The New Kid" using clues from the surrounding text.', 'Guesses a word from how it looks instead of using the words around it.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Reading', 'READ-Y6-A1-W1-2', 'Retrieve (2b: retrieve and record): To retrieve and record key details from "The New Kid" and find the evidence that supports them.', 'Answers from memory rather than finding the exact words in the text.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Reading', 'READ-Y6-A1-W1-3', 'Infer (2d: inference from evidence): To infer how a character feels in "The New Kid" and justify it with evidence.', 'Gives an opinion but no evidence from the text to back it.', true),\n  ('03463a9b-adcd-44bd-92be-db2f40a1a6b8'::uuid, 'English Reading', 'READ-Y6-A1-W1-4', 'Predict / Explain (2e and 2g: predict, explain word choice): To predict what a character might do next in "The New Kid" and explain