on conflict (school_id, code) do update
  set subject = excluded.subject,
      statement = excluded.statement,
      hinge = excluded.hinge,
      hinge_suggested = excluded.hinge_suggested;

-- 4. convenience read for the daily layer: objective + hinge by subject
create or replace view v_y6_objectives as
  select id, subject, code, statement, hinge, hinge_suggested, next_step
  from objectives where school_id = my_school();

-- seeded: 96 objectives (8 Maths, 7 Science, 33 Writing, 35 Reading, 13 IPC).
-- 96 carry a hinge; 81 are SEQUENS-suggested (hinge_suggested = true).
